129	export class ObjectSetup implements ISetup<
130	  [Engine, PageConfig],
131	  Promise<void>
132	> {
133	  private readonly _registry = new Map<string, ObjectRegistrationSpec>();
134	  private readonly _configRuntime = new ObjectConfigRuntime();
135	  private _disposed = false;
136	  private static readonly _ENV_ALIAS_BY_OBJECT_ID: Readonly<
137	    Partial<Record<keyof ObjectOptionsByKey, string>>
138	  > = {
139	    [sceneLights]: "env.light",
140	  };
141	
142	  constructor(registry: ObjectFactoryRegistry = createDefaultRegistry()) {
143	    for (const [id, spec] of Object.entries(registry)) {
144	      this._registry.set(id, spec);
145	    }
146	  }
147	
148	  registerFactory(id: string, spec: ObjectRegistrationSpec): void {
149	    this._registry.set(id, spec);
150	  }
151	
152	  register(id: string, spec: ObjectRegistrationSpec): void {
153	    this.registerFactory(id, spec);
154	  }
155	
156	  async init(engine: Engine, pageConfig: PageConfig): Promise<void> {
157	    if (this._disposed) return;
158	    for (const [id, spec] of this._getEnabledSpecs(pageConfig)) {
159	      const object = this._createConfiguredObject(
160	        spec,
161	        pageConfig.objectOptions,
162	        pageConfig.initialState,
163	      );
164	      await engine.setObject(id, object);
165	      this._registerEnvironmentAlias(engine, id as keyof ObjectOptionsByKey);
166	    }
167	  }
168	
169	  dispose(): void {
170	    if (this._disposed) return;
171	    this._disposed = true;
172	    this._registry.clear();
173	  }
174	
175	  private _getEnabledSpecs(
176	    pageConfig: PageConfig,
177	  ): Array<[string, ObjectRegistrationSpec]> {
178	    const enabledSpecs: Array<[string, ObjectRegistrationSpec]> = [];
179	    for (const [id, enabled] of Object.entries(pageConfig.objects)) {
180	      if (!enabled) continue;
181	      const spec = this._registry.get(id);
182	      if (!spec) continue;
183	      enabledSpecs.push([id, spec]);
184	    }
185	    return enabledSpecs;
186	  }
187	
188	  private _createConfiguredObject(
189	    spec: ObjectRegistrationSpec,
190	    pageOptions: PageConfig["objectOptions"] | undefined,
191	    initialState: PageConfig["initialState"] | undefined,
192	  ): SceneObject {
193	    const object = spec.create();
194	    const resolvedConfig = this._configRuntime.resolve(
195	      spec.id,
196	      pageOptions,
197	      initialState,
198	    );
199	    spec.applyOptions?.(object, resolvedConfig.options);
200	    if (resolvedConfig.effects && typeof object.setEffects === "function") {
201	      object.setEffects(resolvedConfig.effects);
202	    }
203	    return object;
204	  }
205	
206	  private _registerEnvironmentAlias(
207	    engine: Engine,
208	    objectId: keyof ObjectOptionsByKey,
209	  ): void {
210	    const envAlias = ObjectSetup._ENV_ALIAS_BY_OBJECT_ID[objectId];
211	    if (!envAlias) return;
212	    const target = engine.getObjectById(objectId as string);
213	    if (!target || typeof target !== "object") return;
214	    engine
215	      .getScene()
216	      .registerObject(envAlias, target as Record<string, unknown>);
217	  }
218	}
