1	import * as THREE from "three";
2	import { SceneObject } from "../../core/SceneObject.js";
3	import type { SceneObjectContext } from "../../types/engine.types.js";
4	import type { GravityBallsObjectOptions } from "../../types/object.types.js";
5	
6	interface SphereInfo {
7	  ID: number;
8	  startX: number;
9	  startY: number;
10	  startZ: number;
11	  vx: number;
12	  vy: number;
13	  vz: number;
14	  gravity: number;
15	  rotDir: number;
16	  shrinkRate: number;
17	  sphere: THREE.Sprite;
18	  material: THREE.SpriteMaterial;
19	}
20	
21	type ResolvedOpts = {
22	  attachTo: string;
23	  spawnOffset: { x?: number; y?: number; z?: number };
24	  colors: string[];
25	  dotsPerInterval: number;
26	  physicsScale: number;
27	};
28	
29	const FADE_START_SCALE = 0.65;
30	const SMOKE_Z_DRIFT = 0.002;
31	const SMOKE_SPREAD = 1.005;
32	const MIN_INIT_SCALE = 0.4;
33	const MAX_INIT_SCALE = 1.0;
34	const LIFETIME_TICKS = 150;
35	
36	const DEFAULT_TEXTURE_URLS = [
37	  "/resource/images/texture/smoke/smoke_01.png",
38	  "/resource/images/texture/rocket/smoke.png",
39	];
40	
41	const DEFAULTS = {
42	  attachTo: "rocket",
43	  spawnOffset: { x: 0 as number, y: -0.34 as number, z: 0 as number },
44	  colors: ["#FFFFFF", "#F5F5F5", "#EEEEEE"] as string[],
45	  dotsPerInterval: 3,
46	  physicsScale: 0.006,
47	};
48	
49	export class GravityBalls extends SceneObject<Record<string, never>> {
50	  private readonly _balls = new Map<number, SphereInfo>();
51	  private _idx = 0;
52	  private _accumMs = 0;
53	  private readonly _spawnPt = new THREE.Vector3();
54	  private _opts: GravityBallsObjectOptions = {};
55	  private _baseMats: THREE.SpriteMaterial[] = [];
56	
57	  setOptions(props: Partial<GravityBallsObjectOptions> | undefined): this {
58	    if (props) this._opts = { ...this._opts, ...props };
59	    return this;
60	  }
61	
62	  protected override getOptions(): Record<string, unknown> {
63	    return this._opts as Record<string, unknown>;
64	  }
65	
66	  override async runObject(): Promise<void> {
67	    const ctx = this._context;
68	    if (!ctx) return;
69	
70	    const urls: string[] =
71	      this._opts.textureUrls?.length ? this._opts.textureUrls
72	      : this._opts.textureUrl ? [this._opts.textureUrl]
73	      : DEFAULT_TEXTURE_URLS;
74	
75	    const textures = await Promise.all(
76	      urls.map(async (url): Promise<THREE.Texture | null> => {
77	        if (!url || !ctx.loadTexture) return null;
78	        try { return await ctx.loadTexture(this.resolveAssetPath(url)); }
79	        catch { return null; }
80	      }),
81	    );
82	
83	    this._baseMats = textures.length > 0
84	      ? textures.map(tex => new THREE.SpriteMaterial({
85	          map: tex ?? null,
86	          transparent: true,
87	          depthWrite: false,
88	          opacity: 0.8,
89	        }))
90	      : [new THREE.SpriteMaterial({ transparent: true, depthWrite: false, opacity: 0.8 })];
91	
92	    this._applyOptionVisibility();
93	  }
94	
95	  override runUpdate(delta: number): void {
96	    const ctx = this._context;
97	    if (!ctx || this._disposed) return;
98	
99	    this._accumMs += delta * 1000;
100	    if (this._accumMs >= 15) {
101	      this._accumMs -= 15;
102	      this._tick(ctx);
103	    }
104	  }
105	
106	  private _tick(ctx: SceneObjectContext): void {
107	    const o = this._resolve();
108	
109	    if (o.attachTo) {
110	      const rkt = ctx.getObject(o.attachTo);
111	      if (rkt instanceof THREE.Object3D) {
112	        rkt.getWorldPosition(this._spawnPt);
113	        this._spawnPt.x += o.spawnOffset.x ?? 0;
114	        this._spawnPt.y += o.spawnOffset.y ?? 0;
115	        this._spawnPt.z += o.spawnOffset.z ?? 0;
116	      }
117	    }
118	
119	    for (let i = 0; i < o.dotsPerInterval; i++) this._spawn(ctx, o);
120	
121	    const dead: number[] = [];
122	    this._balls.forEach((b, id) => { if (this._step(b)) dead.push(id); });
123	    for (const id of dead) this._balls.delete(id);
124	  }
125	
126	  private _spawn(ctx: SceneObjectContext, o: ResolvedOpts): void {
127	    if (this._baseMats.length === 0) return;
128	
129	    const s = o.physicsScale;
130	    const baseMat = this._baseMats[Math.floor(Math.random() * this._baseMats.length)];
131	    const mat = baseMat.clone();
132	
133	    const color = o.colors[this._rnd(0, o.colors.length)] ?? o.colors[0];
134	    mat.color.set(color);
135	    mat.rotation = Math.random() * Math.PI * 2;
136	
137	    const initScale = MIN_INIT_SCALE + Math.random() * (MAX_INIT_SCALE - MIN_INIT_SCALE);
138	    const shrinkRate = -(initScale - 0.1) / LIFETIME_TICKS;
139	
140	    const isXNeg = this._rnd(1, 2) === 1;
141	    const isZNeg = this._rnd(1, 2) === 1;
142	
143	    const sprite = new THREE.Sprite(mat);
144	    sprite.scale.setScalar(initScale);
145	
146	    const info: SphereInfo = {
147	      ID: ++this._idx,
148	      startX: this._spawnPt.x,
149	      startY: this._spawnPt.y,
150	      startZ: this._spawnPt.z,
151	      vx: isXNeg ? this._rnd(0, 50) * -0.15 * s : this._rnd(0, 50) * 0.15 * s,
152	      vy: this._rnd(-10, 20) * s,
153	      vz: isZNeg ? this._rnd(-25, 25) * -0.4 * s : this._rnd(-25, 25) * 0.4 * s,
154	      gravity: 10 * s,
155	      rotDir: (Math.random() < 0.5 ? 1 : -1) * (0.003 + Math.random() * 0.006),
156	      shrinkRate,
157	      sphere: sprite,
158	      material: mat,
159	    };
160	
161	    ctx.scene.add(sprite);
162	    this._balls.set(info.ID, info);
163	  }
164	
165	  private _step(b: SphereInfo): boolean {
166	    const sp = b.sphere;
167	
168	    sp.scale.x += b.shrinkRate;
169	    sp.scale.y += b.shrinkRate;
170	
171	    b.startX += b.vx * 0.6;
172	    b.startY -= b.vy * 0.5;
173	    b.startZ -= b.vz * 0.6;
174	    sp.position.x = b.startX;
175	    sp.position.y = b.startY;
176	    sp.position.z = b.startZ;
177	
178	    b.vy += b.gravity;
179	    b.material.rotation += b.rotDir;
180	
