### 4. SceneObject 베이스 클래스

#### 4.1 SceneObject.ts 전체 구조

**파일 위치**: `/c/Users/edn_y/renew_nineonelabs/resource/ts/core/SceneObject.ts`

**핵심 메서드들**:

```typescript
abstract class SceneObject<TTweenProps = Record<string, unknown>> {
  protected _context: SceneObjectContext | null = null;
  protected _disposed = false;
  private _timelineRoot: THREE.Group | null = null;
  private _effects: ObjectEffects = {};
  private _visible = true;
  private _ownedTextures = new Set<THREE.Texture>();

  // 라이프사이클 메서드
  init(context?: SceneObjectContext): void | Promise<void> {
    if (context) {
      this._context = context;
      return;
    }
    return this.runObject();
  }

  abstract runObject(): void | Promise<void>;    // 초기화 시 호출
  abstract runUpdate(_deltaTime: number): void;  // 매 프레임 호출

  // 다른 오브젝트 참조 패턴
  protected getShaderManager(): ShaderManagerRuntimePort | null {
    const candidate = this._context?.getObject("env.shaderManager.runtime");
    if (!candidate || typeof candidate !== "object") return null;
    return candidate as unknown as ShaderManagerRuntimePort;
  }

  // 시간축 루트 관리
  protected ensureTimelineRoot(name?: string): THREE.Group | null {
    if (this._timelineRoot) return this._timelineRoot;
    const scene = this._context?.scene;
    if (!scene) return null;
    const root = new THREE.Group();
    if (name) root.name = name;
    scene.add(root);
    this._timelineRoot = root;
    this._applyOptionVisibility();
    return root;
  }

  protected attachToTimelineRoot(obj: THREE.Object3D, rootName?: string): void {
    const root = this.ensureTimelineRoot(rootName);
    if (!root) return;
    if (obj.parent && obj.parent !== root) obj.parent.remove(obj);
    root.add(obj);
  }

  // 옵션 병합 (Timeline에서 변경 시)
  setTimelineVars(vars: Partial<TTweenProps>, _kind: "from" | "to"): void {
    if (vars == null || Object.keys(vars as object).length === 0) return;
    const normalized = this.normalizeTimelineVars(
      vars as Record<string, unknown>,
    );
    this.mergeOptionsFromTimeline(normalized as Partial<TTweenProps>);
    this._applyOptionVisibility();
    this.syncFromOptions();
  }

  // 가시성 관리
  setVisibleOn(): void { this._setVisibility(true); }
  setVisibleOff(): void { this._setVisibility(false); }
  getVisibleState(): boolean { return this._visible; }

  private _setVisibility(visible: boolean): void {
    const resolved = this.isAlwaysVisible() ? true : visible;
    this._visible = resolved;
    const options = this.getOptions();
    if (options && typeof options === "object") {
      options.visible = resolved;
    }
    this.applyVisibility(resolved);
  }

  protected _applyOptionVisibility(): void {
    const options = this.getOptions();
    const visible = options.visible;
    if (typeof visible === "boolean") {
      this._setVisibility(visible);
      return;
    }
    if (this.isAlwaysVisible()) this._setVisibility(true);
  }

  // 이펙트 관리
  setEffects(effects: ObjectEffects): void {
    this._effects = { ...effects };
  }

  getEffects(): ObjectEffects {
    return this._effects;
  }

  // 정리
  dispose(): void {
    if (this._disposed) return;
    this._disposed = true;
    for (const texture of this._ownedTextures) texture.dispose();
    this._ownedTextures.clear();
    this.offTimelineRoot();
    this._context = null;
  }

  get isDisposed(): boolean {
    return this._disposed;
  }
}
```

