  private readonly _balls = new Map<number, SphereInfo>();  // 활성 스프라이트
  private _idx = 0;                                           // ID 카운터
  private _accumMs = 0;                                       // 델타 누적
  private readonly _spawnPt = new THREE.Vector3();           // 스폰 위치
