#### 10.3 가시성 관리

```typescript
// setOptions에서 visible 옵션 설정
protected _applyOptionVisibility(): void {
  const options = this.getOptions();
  const visible = options.visible;
  if (typeof visible === "boolean") {
    this._setVisibility(visible);
  }
}

// 실제 가시성 적용 (각 클래스에서 구현)
protected abstract applyVisibility(visible: boolean): void;

// GravityBalls에서 구현
protected override applyVisibility(visible: boolean): void {
  this._balls.forEach(b => { b.sphere.visible = visible; });
}
```

